/**
 * Enriches a CycloneDX SBOM generated by @cyclonedx/cyclonedx-npm with:
 *  - file-type subcomponents for the shipped package contents (SHA-256 each)
 *  - dependency integrity hashes taken from package-lock.json
 * Usage: node scripts/enrich-sbom.js [sbom-file]
 */
const fs = require("fs");
const crypto = require("crypto");

const path = process.argv[2] || "sbom.cdx.json";
const bom = JSON.parse(fs.readFileSync(path, "utf8"));

const shippedFiles = ["index.js", "package.json", "README.md"];
const fileComponents = shippedFiles.map((name) => ({
  type: "file",
  name,
  hashes: [
    {
      alg: "SHA-256",
      content: crypto.createHash("sha256").update(fs.readFileSync(name)).digest("hex"),
    },
  ],
}));

bom.metadata.components = (bom.metadata.components || []).concat(fileComponents);

const HASH_ALGS = { sha512: "SHA-512", sha384: "SHA-384", sha256: "SHA-256", sha1: "SHA-1" };
const lock = JSON.parse(fs.readFileSync("package-lock.json", "utf8"));
for (const comp of bom.components || []) {
  const entry = (lock.packages || {})[`node_modules/${comp.name}`];
  if (!entry || entry.version !== comp.version || comp.hashes) continue;
  const dash = entry.integrity.indexOf("-");
  const alg = HASH_ALGS[entry.integrity.slice(0, dash)];
  if (!alg) continue;
  const content = Buffer.from(entry.integrity.slice(dash + 1), "base64").toString("hex");
  comp.hashes = [{ alg, content }];
}

fs.writeFileSync(path, JSON.stringify(bom, null, 2) + "\n");
